cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && awk -F'|' '{print $5"|"$2}' /tmp/msgs.tsv | sort -u > /tmp/ep_sha.tsv; wc -l /tmp/ep_sha.tsv
python3 - <<'EOF'
import re,subprocess,collections
declared=collections.defaultdict(set)
for line in open('/tmp/ep_sha.tsv'):
    ep,sha=line.strip().split('|')
    declared[ep].add(sha)
files=subprocess.check_output(['git','ls-tree','-r','--name-only','origin/main'],text=True).split()
recorded=collections.defaultdict(set)
for f in files:
    if re.match(r'^S\d+/E\d+\.md$',f):
        txt=subprocess.check_output(['git','show',f'origin/main:{f}'],text=True)
        for m in re.finditer(r'^Source: friend/\w+ @ ([0-9a-f]{40})',txt,re.M):
            recorded[f[:-3]].add(m.group(1))
for ep in sorted(set(declared)|set(recorded)):
    d=declared.get(ep,set()); r=recorded.get(ep,set())
    if d!=r:
        print(ep,'declared',len(d),'recorded',len(r),'missing',len(d-r),'extra',len(r-d))
EOF
